var DATA = {"issue": "Open boundary", "fix": "Ear-clipping fill", "mesh": "v0:0,0,0;v1:1,0,0;v2:1,1,0;v3:0,1,0|f0:v0,v1,v2|f1:v0,v2,v3"};
console.log("Issue: " + DATA.issue + " | Repair: " + DATA.fix);
// sample_mesh like "v0:0,0,0;v1:1,0,0|f0:v0,v1,v2|f1:v1,v3,v2" — count edge usage to find non-manifold edges
var parts = DATA.mesh.split("|");
var verts = {}, edgeUse = {};
parts.forEach(function (p) {
  var kv = p.split(":"); var kind = kv[0].trim();
  if (kind[0] === "v") { verts[kind] = kv[1]; }
  else if (kind[0] === "f") {
    var vs = kv[1].split(",").map(function (s) { return s.trim(); });
    for (var i = 0; i < vs.length; i++) {
      var a = vs[i], b = vs[(i + 1) % vs.length];
      var e = a < b ? a + "-" + b : b + "-" + a;
      edgeUse[e] = (edgeUse[e] || 0) + 1;
    }
  }
});
var boundary = [], nonman = [];
Object.keys(edgeUse).forEach(function (e) {
  if (edgeUse[e] === 1) boundary.push(e);
  else if (edgeUse[e] > 2) nonman.push(e);
});
console.log("Vertices: " + Object.keys(verts).length + " | Edges: " + Object.keys(edgeUse).length);
console.log("Boundary edges (holes): " + (boundary.length ? boundary.join(", ") : "none"));
console.log("Non-manifold edges: " + (nonman.length ? nonman.join(", ") : "none"));
var ok = boundary.length === 0 && nonman.length === 0;
console.log("RESULT: mesh is " + (ok ? "WATERTIGHT" : "defective") + " — repair method: " + DATA.fix + ".");

